// Service worker registration generated by `cargo rullst make:pwa`.
// A same-origin file, so the default Content-Security-Policy (`script-src 'self'`)
// allows it without a nonce. It sets no `style` attribute, which that policy
// refuses: the update notice is styled by classes.
(function () {
  'use strict';
  if (!('serviceWorker' in navigator)) return;
  var container = navigator.serviceWorker;
  var reloadRequested = false;
  var shown = false;
  // The texts of the update notice, in the language make:pwa was given.
  var TEXT = {
    update: 'A new version of this app is available.',
    reload: 'Reload',
  };
  // The default look of the classes pwa-update, pwa-update-text and
  // pwa-update-button. Its rules use :where(), so the application's own
  // rules for these classes win; it loads only when the notice shows.
  var STYLESHEET = '/static/pwa.css';

  function present(bar) {
    function show() {
      document.body.appendChild(bar);
    }
    if (document.querySelector('link[href="' + STYLESHEET + '"]')) {
      show();
      return;
    }
    var sheet = document.createElement('link');
    sheet.rel = 'stylesheet';
    sheet.href = STYLESHEET;
    sheet.onload = show;
    sheet.onerror = show;
    document.head.appendChild(sheet);
  }

  // A new worker is installed and waiting: offer a reload instead of
  // swapping the code under a page that is in use.
  function showUpdate(worker) {
    if (shown) return;
    shown = true;
    var bar = document.createElement('div');
    bar.id = 'rullst-pwa-update';
    bar.className = 'pwa-update';
    bar.setAttribute('role', 'status');
    var text = document.createElement('span');
    text.className = 'pwa-update-text';
    text.textContent = TEXT.update;
    var button = document.createElement('button');
    button.className = 'pwa-update-button';
    button.type = 'button';
    button.textContent = TEXT.reload;
    button.addEventListener('click', function () {
      reloadRequested = true;
      button.disabled = true;
      worker.postMessage({ type: 'SKIP_WAITING' });
    });
    bar.appendChild(text);
    bar.appendChild(button);
    present(bar);
  }

  function watch(registration) {
    if (registration.waiting && container.controller) showUpdate(registration.waiting);
    registration.addEventListener('updatefound', function () {
      var worker = registration.installing;
      if (!worker) return;
      worker.addEventListener('statechange', function () {
        // Without a controller this is the first install, not an update.
        if (worker.state === 'installed' && container.controller) showUpdate(worker);
      });
    });
  }

  // Reload once the new worker controls the page, only when the user asked:
  // the first install also changes the controller.
  container.addEventListener('controllerchange', function () {
    if (!reloadRequested) return;
    reloadRequested = false;
    window.location.reload();
  });

  function register() {
    container.register('/sw.js', { scope: '/' }).then(watch, function (error) {
      if (window.console) window.console.warn('Service worker registration failed:', error);
    });
  }

  if (document.readyState === 'complete') {
    register();
  } else {
    window.addEventListener('load', register);
  }
})();
